"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is streamed; only the accounts file is held whole. The v3 file has to be sorted, so records are sorted
by spilling sorted runs to a scratch directory beside dst and merging them. The output goes to dst.partial and is
renamed over dst only once every line has migrated, so a failed run leaves dst as it was.
"""
import contextlib
import heapq
import json
import os
import tempfile

from . import kinds, money, timefmt, v2, v3
from .accounts import load as load_accounts
from .errors import FormatError, MigrationError

CHUNK_RECORDS = 250_000  # records held in memory before a sorted run is spilled to disk
FAN_IN = 100  # runs merged at once, which bounds how many run files are open at once


def migrate(src, accounts, dst):
    held = load_accounts(accounts)
    partial = f"{dst}.partial"
    try:
        scratch_parent = os.path.dirname(os.path.abspath(dst))
        with tempfile.TemporaryDirectory(dir=scratch_parent, prefix=".migrate-") as scratch:
            with open(partial, "w", encoding="utf-8", newline="\n") as out:
                count = _write(src, held, out, scratch)
                out.flush()
                os.fsync(out.fileno())
        os.replace(partial, dst)
    except BaseException:
        with contextlib.suppress(OSError):
            os.remove(partial)
        raise
    return count


def _write(src, held, out, scratch):
    # Every line is migrated, superseded revisions included, so one bad line anywhere stops the run.
    by_id = _RunSorter(scratch, "by-id")
    for number, text in _lines(src):
        record = _convert(text, number, held)
        by_id.add((record["id"], record["source_rev"], number), record)
    by_place = _RunSorter(scratch, "by-place")
    for record in _latest_revisions(by_id.sorted_items()):
        by_place.add((record["account"], record["posted_at"], record["id"]), record)
    count = 0
    for _, record in by_place.sorted_items():
        out.write(v3.dump_line(record))
        count += 1
    return count


def _lines(path):
    """(line number, text) for every line that isn't blank."""
    with open(path, encoding="utf-8") as f:
        number = 0
        try:
            for text in f:
                number += 1
                if text.strip():
                    yield number, text
        except UnicodeDecodeError as e:
            raise MigrationError(f"not UTF-8 ({e.reason})", number + 1) from None


def _convert(text, number, held):
    """The v3 record for one v2 line. MigrationError when the line can't be migrated."""
    try:
        raw = json.loads(text)
    except ValueError as e:
        raise MigrationError(f"not JSON ({e})", number) from None
    try:
        v2.check(raw, number)
    except FormatError as e:
        raise MigrationError(str(e)) from None
    account = held.get(raw["account"])
    if account is None:
        raise MigrationError(f"account {raw['account']!r} isn't in the accounts file", number)
    kind = kinds.LEGACY.get(raw["kind"], raw["kind"])
    if kind not in kinds.TYPES:
        raise MigrationError(f"unknown kind {raw['kind']!r}", number)
    currency = account.currency if raw["currency"] is None else raw["currency"]
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", number)
    try:
        minor = money.to_minor(raw["amount"], currency)
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    if minor <= 0:
        raise MigrationError(f"amount {raw['amount']} isn't positive", number)
    try:
        stamp = timefmt.parse_ts(raw["ts"])
        if stamp.tzinfo is None:
            # 2020 bulk-import times carry no offset; they are the account's local time.
            stamp = stamp.replace(tzinfo=account.tz)
        posted_at = timefmt.to_utc_z(stamp)
    except (ValueError, OverflowError) as e:
        raise MigrationError(str(e), number) from None
    record = {"id": raw["id"], "account": raw["account"], "type": kind,
              "amount_minor": kinds.SIGN[kind] * minor, "currency": currency, "posted_at": posted_at,
              "memo": raw["memo"], "source_rev": raw["rev"]}
    try:
        v3.validate(record, number)
    except FormatError as e:
        raise MigrationError(str(e)) from None
    return record


def _latest_revisions(sorted_items):
    """The current revision of each entry. Items arrive sorted by (id, rev, line), so the last item of each id is
    the current one."""
    pending = None
    for _, record in sorted_items:
        if pending is not None and pending["id"] != record["id"]:
            yield pending
        pending = record
    if pending is not None:
        yield pending


class _RunSorter:
    """Sorts records by key without holding them all in memory. Full buffers are sorted and spilled to disk as
    runs; the runs are merged when the records are read back."""

    def __init__(self, scratch, name):
        self.scratch = scratch
        self.name = name
        self.buffer = []
        self.runs = []
        self.made = 0

    def add(self, key, record):
        self.buffer.append((key, record))
        if len(self.buffer) >= CHUNK_RECORDS:
            self._spill()

    def sorted_items(self):
        """Every (key, record) in key order. Call once, after the last add."""
        if not self.runs:
            self.buffer.sort(key=_first)
            return iter(self.buffer)
        self._spill()
        while len(self.runs) > FAN_IN:
            group, self.runs = self.runs[:FAN_IN], self.runs[FAN_IN:]
            merged = self._new_path()
            _write_run(merged, _merge(group))
            self.runs.append(merged)
        return _merge(self.runs)

    def _spill(self):
        if self.buffer:
            self.buffer.sort(key=_first)
            path = self._new_path()
            _write_run(path, self.buffer)
            self.runs.append(path)
            self.buffer = []

    def _new_path(self):
        self.made += 1
        return os.path.join(self.scratch, f"{self.name}-{self.made}.run")


def _first(item):
    return item[0]


def _merge(paths):
    return heapq.merge(*(_read_run(p) for p in paths), key=_first)


def _write_run(path, items):
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        for key, record in items:
            f.write(json.dumps([list(key), record], ensure_ascii=False, separators=(",", ":")) + "\n")


def _read_run(path):
    """A run is read once, so it is deleted when it has been read to the end. That keeps scratch space bounded."""
    with open(path, encoding="utf-8") as f:
        for line in f:
            key, record = json.loads(line)
            yield tuple(key), record
    os.remove(path)

