def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three statements whatever the data size. ORDER BY keeps each account's invoices, and each invoice's
    # payments, in the id order the old per-account queries returned, so the arithmetic runs in the same sequence.
    result = {account_id: 0 for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall()}
    invoices = conn.execute(
        "SELECT account_id, id, amount_cents FROM invoices WHERE voided = 0 ORDER BY account_id, id").fetchall()
    payments_by_invoice = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT invoice_id, amount_cents, status, method FROM payments "
            "WHERE invoice_id IN (SELECT id FROM invoices WHERE voided = 0) ORDER BY invoice_id, id").fetchall():
        payments_by_invoice.setdefault(invoice_id, []).append((paid, status, method))
    for account_id, invoice_id, cents in invoices:
        if account_id not in result:
            continue  # invoice of an account that isn't in accounts: never reported, as before
        result[account_id] += cents
        for paid, status, method in payments_by_invoice.get(invoice_id, ()):
            if rules.counts(status, method):
                result[account_id] -= paid
    return result

