def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three whole-table queries, combined in Python with dicts (linear in the data).
    # Keys are created in the order of the accounts query, as before.
    result = {account_id: 0 for (account_id,) in conn.execute("SELECT id FROM accounts").fetchall()}

    # Only non-voided invoices of accounts that exist contribute, as before.
    invoice_account = {}
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0").fetchall():
        if account_id in result:
            invoice_account[invoice_id] = account_id
            result[account_id] += cents

    # Payments only count against those invoices, and only when rules.counts accepts them.
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method"
            " FROM payments p JOIN invoices i ON i.id = p.invoice_id"
            " WHERE i.voided = 0").fetchall():
        account_id = invoice_account.get(invoice_id)
        if account_id is not None and rules.counts(status, method):
            result[account_id] -= paid
    return result

