"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is far too big to hold in memory, so this is two external merge sorts over temporary files:

1. Every v2 line is spilled, in bounded chunks, into sorted runs keyed by (id, rev, line number). Merging the
   runs brings all lines of an entry together, and the last one of each id is its current revision (highest rev,
   later line wins on a tie).
2. Each current revision is converted to a v3 record and spilled into sorted runs keyed by (account, posted_at,
   id); merging those yields the v3 file in order.

Output goes to a temporary file next to dst and is renamed into place only when everything succeeded, so a
MigrationError (or any other failure) leaves nothing at dst.
"""
import heapq
import json
import os
import tempfile

from . import accounts as accounts_file
from . import kinds, money, timefmt, v2, v3
from .errors import FormatError, MigrationError

CHUNK = 200_000  # lines held in memory at once while building a sorted run


class _Runs:
    """Sorted runs of JSON-encoded items on disk, merged back in key order."""

    def __init__(self, tmpdir, key):
        self.tmpdir, self.key, self.paths, self.buffer = tmpdir, key, [], []

    def add(self, item):
        self.buffer.append(item)
        if len(self.buffer) >= CHUNK:
            self._spill()

    def _spill(self):
        if not self.buffer:
            return
        self.buffer.sort(key=self.key)
        fd, path = tempfile.mkstemp(suffix=".run", dir=self.tmpdir)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            for item in self.buffer:
                f.write(json.dumps(item, ensure_ascii=False, separators=(",", ":")) + "\n")
        self.paths.append(path)
        self.buffer = []

    def merged(self):
        self._spill()
        files = [open(p, encoding="utf-8") for p in self.paths]
        try:
            yield from heapq.merge(*((json.loads(t) for t in f) for f in files), key=self.key)
        finally:
            for f in files:
                f.close()


def _read_v2(path):
    """(line number, record) for every non-blank line, streamed."""
    with open(path, encoding="utf-8") as f:
        for number, text in enumerate(f, 1):
            if not text.strip():
                continue
            try:
                record = json.loads(text)
            except ValueError as e:
                raise MigrationError(f"not JSON ({e})", number) from None
            try:
                v2.check(record, number)
            except FormatError as e:
                raise MigrationError(str(e), number) from None
            yield number, record


def _current_revisions(lines):
    """From lines sorted by (id, rev, line number), the last line of each id."""
    held = None
    for item in lines:
        if held is not None and held[1]["id"] != item[1]["id"]:
            yield held
        held = item
    if held is not None:
        yield held


def _convert(number, line, accounts):
    account = accounts.get(line["account"])
    if account is None:
        raise MigrationError(f"account {line['account']!r} isn't in the accounts file", number)
    entry_type = kinds.LEGACY.get(line["kind"], line["kind"])
    if entry_type not in kinds.TYPES:
        raise MigrationError(f"unknown kind {line['kind']!r}", number)
    # Until 2022 a null currency meant the account's own.
    currency = line["currency"] if line["currency"] is not None else account.currency
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", number)
    try:
        minor = money.to_minor(line["amount"], currency)
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    if minor < 0:
        raise MigrationError(f"amount {line['amount']} isn't positive", number)
    try:
        stamp = timefmt.parse_ts(line["ts"])
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    if stamp.tzinfo is None:
        # The 2020 bulk importer wrote the account's local time without an offset.
        stamp = stamp.replace(tzinfo=account.tz)
    record = {"id": line["id"], "account": line["account"], "type": entry_type,
              "amount_minor": kinds.SIGN[entry_type] * minor, "currency": currency,
              "posted_at": timefmt.to_utc_z(stamp), "memo": line["memo"], "source_rev": line["rev"]}
    try:
        v3.validate(record)
    except FormatError as e:
        raise MigrationError(str(e), number) from None
    return record


def migrate(src, accounts, dst):
    try:
        known = accounts_file.load(accounts)
    except FormatError as e:
        raise MigrationError(f"accounts file: {e}") from None
    dst = os.fspath(dst)
    with tempfile.TemporaryDirectory(prefix="migrate_v3-") as tmpdir:
        by_id = _Runs(tmpdir, key=lambda item: (item[1]["id"], item[1]["rev"], item[0]))
        for number, record in _read_v2(src):
            by_id.add([number, record])

        in_order = _Runs(tmpdir, key=v3.order_key)
        for number, line in _current_revisions(by_id.merged()):
            in_order.add(_convert(number, line, known))

        fd, part = tempfile.mkstemp(prefix=".ledger_v3-", suffix=".part", dir=os.path.dirname(dst) or ".")
        try:
            count = 0
            with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as out:
                for record in in_order.merged():
                    out.write(v3.dump_line(record))
                    count += 1
            umask = os.umask(0)
            os.umask(umask)
            os.chmod(part, 0o666 & ~umask)  # mkstemp makes it 0600; give it a normal file's permissions
            os.replace(part, dst)
        except BaseException:
            if os.path.exists(part):
                os.remove(part)
            raise
    return count

